import csv
from collections import defaultdict

rows = []
with open('results/exp041_asymmetric_summary.csv') as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append(r)

# R2 table by ratio x K x delta_pi
print('=== R2 by ratio x K x delta_pi ===')
for K in ['2','4']:
    print(f'\nK={K}:')
    print(f'ratio  | dp=0.05 | dp=0.10 | dp=0.15 | dp=0.20')
    for ratio in ['1:2','1:3','1:5','2:1','3:1','5:1']:
        vals = {}
        for r in rows:
            if r['method']=='oracle' and r['K']==K and r['fpr_fnr_ratio']==ratio:
                vals[r['delta_pi']] = float(r['r2'])
        print(f'{ratio:6s} | {vals.get(\"0.05\",0):.2f}    | {vals.get(\"0.1\",0):.2f}    | {vals.get(\"0.15\",0):.2f}    | {vals.get(\"0.2\",0):.2f}')

# Diagnostic AUC
print('\n=== Diagnostic AUC ===')
for K in ['2','4']:
    aucs = []
    for r in rows:
        if r['method']=='oracle' and r['K']==K and r['diagnostic_auc']:
            aucs.append(float(r['diagnostic_auc']))
    if aucs:
        print(f'K={K}: n={len(aucs)}, mean={sum(aucs)/len(aucs):.2f}, min={min(aucs):.2f}, max={max(aucs):.2f}')
    else:
        print(f'K={K}: no AUC data')

# Method comparison by K
print('\n=== Method comparison by K ===')
for K in ['2','4']:
    print(f'\nK={K}:')
    for m in ['oracle','naive','global_corrected','ec_hte']:
        vals_b, vals_r, vals_c = [],[],[]
        for r in rows:
            if r['method']==m and r['K']==K:
                vals_b.append(float(r['mean_abs_bias']))
                vals_r.append(float(r['rmse']))
                vals_c.append(float(r['coverage']))
        n = len(vals_b)
        print(f'  {m}: abs_bias={sum(vals_b)/n:.3f}, rmse={sum(vals_r)/n:.3f}, cov={sum(vals_c)/n:.3f}')
"
